#!/usr/bin/env python3 -I
"""Лічба звіту: питання 1–2 (знахідки вироку руки 1) і 3–4 (блок «Чого я не знаю»). Запуск з теки звіту: python3 -I аналіз/лічба.py"""
import json, re, glob, os
ТЕКА = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def читати(п): return open(os.path.join(ТЕКА, п), encoding="utf-8").read()
print("# питання 1–2: вирок руки 1 (вердикти.txt → прогони[0].вердикти[0].знахідки_коду), суд.знахідки == знахідки_коду")
for д in ["ж3_свято_др_взуття_фото", "ж3_свято_др_взуття_фото__прохід2", "ж1_театр_максі_підбір", "ж1_театр_максі_підбір__прохід2"]:
    в = json.loads(читати(д + "/вердикти.txt"))["прогони"][0]["вердикти"][0]
    ск = lambda л: sorted((f["правило"], f["сила_нп"], tuple(f.get("речі") or [])) for f in л)
    вирок = в["знахідки_коду"]; суд = в["етапи"]["суд"]["знахідки"]
    взуття = [(f["правило"], f["сила_нп"]) for f in вирок if re.match(r"K-(SHO|HOS)", f["правило"])]
    інше = [(f["правило"], f["сила_нп"]) for f in вирок if re.search(r"взутт|панчох|колгот|туфл", f["суть"], re.I) and not re.match(r"K-(SHO|HOS)", f["правило"])]
    print(f"{д}: рука {в['рука']} · знахідок у вироку {len(вирок)} · у суді {len(суд)} · суд∖вирок {len([x for x in ск(суд) if x not in ск(вирок)])} · "
          f"K-SHO/HOS {взуття} · інші про взуття {інше} · K-SHO-04 ≥0,05: {[x for x in взуття if x[0]=='K-SHO-04' and x[1]>=0.05]}")
print("\n# питання 3–4: блок «Чого я не знаю» (знімки/otsinka_nezn_*.txt): кодові = рядки з входи/чому/повідомлення; латиниця = слова a_b чи held/passed у тексті рядків")
for д in sorted(glob.glob(ТЕКА + "/ж1_17102_краї_*")):
    д = os.path.basename(д); ф = glob.glob(os.path.join(ТЕКА, д, "знімки/otsinka_nezn_*seed3.txt"))[0]
    т = open(ф, encoding="utf-8").read(); j = json.loads(т[:т.index("\n\n")]); не = j["не_знаю"]
    код = [x for x in не if x["входи"] or x["повідомлення"] or x["чому"]]; мод = [x for x in не if x not in код]
    лат = [w for x in не for w in re.findall(r"\b[a-z]+_[a-z_]+\b|\b(?:held|passed|layer_hems\w*)\b", x["текст"])]
    краї = [x for x in мод if re.search(r"подол|поділ|довжин|край|краї", x["текст"])]
    лог = open(os.path.join(ТЕКА, д, "лог.txt"), encoding="utf-8").read().split("\n")
    стан = [re.search(r'"стан_запиту":"(\w+)"', р).group(1) for р in лог if "17102: {" in р and "стан_запиту" in р]
    print(f"{д}: блок розгорнуто {j['блок']} · рядків {len(не)} · кодових {len(код)} · модельних {len(мод)} · про краї серед модельних {len(краї)} · латиниця {лат} · стан_запиту {стан}")
